'use strict';
const defaults={light:{backdrop:'#F4F5EF',foreground:'#243229',surface:'#FFFFFF',accent:'#405B38',onAccent:'#FFFFFF',hover:'#30462B',border:'#788373',error:'#B52D25',focus:'#7253A0'},dark:{backdrop:'#101610',foreground:'#E6EDDF',surface:'#20291F',accent:'#B7D59D',onAccent:'#1D2B16',hover:'#CBE6B4',border:'#829477',error:'#FF9E91',focus:'#C5AFF5'}};
let palettes=structuredClone(defaults),theme='light',state='default',focused=false,lang='en',format='json',snapshotText='',lastReport=null;
const actualFocus=new Set();
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(en,zh)=>lang==='zh'?zh:en;
const names={backdrop:['Backdrop','底色'],foreground:['Foreground','文字'],surface:['Surface','背景'],accent:['Button','按钮背景'],onAccent:['On accent','按钮文字'],hover:['Hover','悬停背景'],border:['Border','边框'],error:['Error','报错'],focus:['Focus ring','焦点描边']};
const styles={default:['Default','默认'],hover:['Hover','悬停'],error:['Error','报错'],disabled:['Disabled','禁用']};
function scaffold(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('#language').textContent=lang==='en'?'简体中文':'English';$('#app').innerHTML=`<section class="intro"><div><h1>${tr('Color contrast','配色对比')}</h1><p class="dek">${tr('Adjust your colors. Compare every state.','调整颜色，看看不同状态下是否清晰。')}</p></div><span class="privacy-label">${tr('Local only','仅在本地处理')}</span></section><nav class="mode-links"><a href="#lab">${tr('Preview','配色预览')}</a><a href="#snapshot">${tr('Inspect an element','检查网页元素')}</a><a href="#export">${tr('Export','导出配色')}</a></nav><section id="lab" class="workbench"><aside class="editor"><div class="section-heading"><h2>${tr('Colors','颜色')}</h2><button id="reset" class="text-button">${tr('Reset all','全部重置')}</button></div><div class="segmented"><button data-theme="light">${tr('Light','浅色')}</button><button data-theme="dark">${tr('Dark','深色')}</button></div><p class="hint">${tr('HEX / RGB / RGBA','HEX / RGB / RGBA')}</p><div id="tokens"></div></aside><div class="stage"><div class="section-heading"><h2>${tr('Preview','预览')}</h2><span class="live">${tr('SIMULATION','模拟')}</span></div><div class="state-controls">${Object.entries(styles).map(([k,v])=>`<button data-state="${k}">${lang==='zh'?v[1]:v[0]}</button>`).join('')}<label class="focus-toggle"><input id="focus-toggle" type="checkbox" ${focused?'checked':''}> ${tr('Show focus','显示焦点')}</label></div><p id="state-note" class="hint"></p><div class="preview-grid" id="previews"></div><div class="matrix-head"><h3>${tr('Contrast','对比度')}</h3><span>WCAG 2.2 · sRGB</span></div><div id="matrix"></div><details class="matrix-note"><summary>${tr('Calculation details','计算说明')}</summary><p>${tr('Solid sRGB layers: backdrop → surface → fill → text. Disabled controls use 40% group opacity. Focus ratios assume a uniform background; size and visibility still need checking.','按底色、背景、填充、文字依次合成。禁用控件透明度为 40%。焦点仅计算均匀背景下的对比度，还需检查描边大小与是否被遮挡。')}</p></details></div></section><section id="snapshot" class="snapshot-section"><div class="section-heading"><h2>${tr('Inspect an element','检查网页元素')}</h2><span class="badge">${tr('Text color','文字对比度')}</span></div><p>${tr('Capture an element’s styles on your page, then paste its JSON below.','采集网页元素的样式，将 JSON 粘贴到下方。')}</p><div class="snapshot-actions"><button id="collector">${tr('Copy collector','复制采集代码')}</button><a href="capture.js" target="_blank" rel="noopener">${tr('View code','查看代码')}</a><button id="example">${tr('Try example','试用示例')}</button></div><details class="collector-help"><summary>${tr('How to capture','如何采集')}</summary><p>${tr('1. Select a leaf text element as $0. 2. Paste the reviewed collector source. 3. Set the actual opaque canvas color; only confirm unobscured after visual review. 4. Copy the returned JSON. Manually visit each desired state and capture again.','1. 选择只包含文字的元素 $0。2. 粘贴审阅过的采集代码。3. 填写页面底色，确认元素未被遮挡。4. 复制返回的 JSON。每种状态须自行进入并重新采集。')}</p><code>copy(JSON.stringify(StateLensCapture($0, { backdrop: '#FFFFFF', confirmUnobscured: true }), null, 2))</code><p>${tr('Do not blindly paste scripts on unfamiliar pages. No network request is made; inspect the JSON before sharing.','不要在不熟悉的页面盲目粘贴脚本。采集器不发送网络请求；分享前请检查 JSON。')}</p></details><label for="snapshot-json">${tr('Style JSON','样式 JSON')}</label><textarea id="snapshot-json" spellcheck="false" placeholder='{"schemaVersion":1,"pairs":[...]}'></textarea><div class="snapshot-actions"><button id="analyze">${tr('Check contrast','检查对比度')}</button><button id="report">${tr('Download report','下载报告')}</button></div><div id="snapshot-status" role="status"></div><div id="snapshot-result"></div></section><section id="export" class="handoff"><div><h2>${tr('Export colors','导出配色')}</h2><p>${tr('Use CSS in your project, or save JSON for later.','复制 CSS 用于项目，或保存 JSON。')}</p></div><div class="export-panel"><div class="section-heading"><div class="segmented"><button data-format="json">JSON</button><button data-format="css">CSS</button></div><button id="copy">${tr('Copy','复制')}</button></div><textarea id="code" readonly aria-label="${tr('Exported token data','导出的配色数据')}"></textarea><div class="export-bottom"><span id="status" role="status"></span><button id="download">${tr('Download','下载')}</button></div></div></section><section id="method" class="method"><details><summary>${tr('About the results','结果说明')}</summary><p>${tr('Ratios describe the selected colors, not complete accessibility conformance. Imported snapshots capture one text element at one moment. Gradients, images, shadows, opacity groups and unverified overlap are marked unsupported.','结果只针对选定颜色。导入的样式仅反映采集时的文字元素；渐变、图片、阴影、组透明度或未确认的遮挡会显示“无法判断”。')}</p><p>${tr('Disabled controls are exempt from contrast requirements; readability suggestions are shown separately.','禁用控件不受对比度最低要求约束，可读性建议单独显示。')}</p><a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener">WCAG 2.2 ↗</a></details><div class="apca-tools"><span>${tr('APCA · external tool','APCA · 外部工具')}</span><a href="https://www.myndex.com/APCA/" target="_blank" rel="noopener">${tr('Open ↗','打开 ↗')}</a><button id="apca-pair" class="text-button">${tr('Copy text/background colors','复制文字与背景色')}</button></div></section>`;
$('#snapshot-json').value=snapshotText;bind();tokens();render();}
function tokens(){$('#tokens').innerHTML=Object.entries(names).map(([k,v])=>`<label class="token"><span class="token-label">${lang==='zh'?v[1]:v[0]}</span><span class="token-input"><span class="swatch" style="background:${esc(palettes[theme][k])}"></span><input data-token="${k}" aria-label="${esc(lang==='zh'?v[1]:v[0])}" aria-invalid="false" aria-describedby="invalid-${k}" value="${esc(palettes[theme][k])}" maxlength="64" spellcheck="false"></span><span id="invalid-${k}" class="invalid">${tr('Invalid / unsupported color. Backdrop must be opaque. Last valid value retained.','无效或不支持的颜色。底色必须不透明，保留上个有效值。')}</span></label>`).join('');document.querySelectorAll('[data-token]').forEach(el=>el.oninput=()=>{const p=Contrast.parse(el.value),valid=p&&(el.dataset.token!=='backdrop'||p.a===1);el.setAttribute('aria-invalid',String(!valid));if(!valid){$('#status').textContent=tr('Invalid input: export uses last valid colors.','输入无效：导出仍使用上个有效颜色。');return;}palettes[theme][el.dataset.token]=Contrast.toCss(p);el.previousElementSibling.style.background=palettes[theme][el.dataset.token];render();});}
function resolved(t){const p=palettes[t],surface=Contrast.evaluate(p.foreground,p.surface,p.backdrop).background,fill=Contrast.evaluate(p.onAccent,p[state==='hover'?'hover':'accent'],Contrast.toCss(surface));return {p,surface,fill};}
function ratioPair(t,key,bgKey,inactive=false){const {p,surface,fill}=resolved(t);let bg=bgKey==='fill'?fill.background:surface;let fg=Contrast.evaluate(p[key],Contrast.toCss(bg),p.backdrop).foreground;if(state==='disabled'&&bgKey==='fill'){fg=Contrast.composite({...fg,a:.4},surface);bg=Contrast.composite({...bg,a:.4},surface);}else if(state==='disabled'&&inactive){fg=Contrast.composite({...fg,a:.4},surface);}return {ratio:Contrast.ratio(fg,bg),foreground:fg,background:bg};}
function render(){document.querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===theme)));document.querySelectorAll('[data-state]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.state===state)));$('#focus-toggle').disabled=state==='disabled';$('#state-note').textContent=state==='disabled'?tr('Disabled · 40% opacity','禁用 · 40% 透明度'):'';const previews=$('#previews');if(!previews.children.length)previews.innerHTML=['light','dark'].map(t=>`<article class="preview" data-preview="${t}"><div class="preview-label">${t==='light'?tr('LIGHT','浅色'):tr('DARK','深色')}</div><h3>${tr('New project','新建项目')}</h3><p>${tr('Start with a name.','为项目起个名字。')}</p><label class="sample-label" for="sample-${t}">${tr('Project name','项目名称')}</label><input class="sample-input" id="sample-${t}" value="${tr('Field notes','灵感笔记')}"><div class="error-message"></div><button class="sample-button" type="button">${tr('Create project ↗','创建项目 ↗')}</button></article>`).join('');
if(!previews.dataset.focusBound){previews.dataset.focusBound='true';previews.addEventListener('focusin',e=>{const card=e.target.closest('[data-preview]');if(card&&e.target.matches(':focus-visible')){actualFocus.add(card.dataset.preview);render();}});previews.addEventListener('focusout',e=>{const card=e.target.closest('[data-preview]');if(card){actualFocus.delete(card.dataset.preview);render();}});}
for(const t of ['light','dark']){const el=previews.querySelector(`[data-preview="${t}"]`),{p,surface,fill}=resolved(t);for(const [k,v]of Object.entries(p))el.style.setProperty('--'+k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase()),v);el.style.setProperty('--surface',Contrast.toCss(surface));el.style.setProperty('--accent',Contrast.toCss(fill.background));el.style.setProperty('--hover',Contrast.toCss(Contrast.evaluate(p.onAccent,p.hover,Contrast.toCss(surface)).background));el.dataset.state=state;el.dataset.focus=String((focused||actualFocus.has(t))&&state!=='disabled');const input=el.querySelector('input'),button=el.querySelector('button');input.disabled=button.disabled=state==='disabled';input.setAttribute('aria-invalid',String(state==='error'));el.querySelector('.error-message').textContent=state==='error'?tr('A project with this name already exists.','已存在同名项目。'):'';button.onclick=()=>$('#status').textContent=tr('Specimen only. Nothing submitted.','仅为示例，没有提交任何内容。');}
const pairs=[[tr('Body & label','正文与标签'),'foreground','surface',4.5,false],[tr('Input text','输入框文字'),'foreground','surface',4.5,true],[tr('Button label','按钮文字'),'onAccent','fill',4.5,true],[tr('Input edge','输入框边界'),state==='error'?'error':state==='hover'?'foreground':'border','surface',3,true]];if(state==='error')pairs.push([tr('Error message','错误文字'),'error','surface',4.5,false]);if((focused||actualFocus.size)&&state!=='disabled')pairs.push([tr('Focus / uniform surface','焦点／均匀表面'),'focus','surface',3,false]);$('#matrix').innerHTML=`<div class="matrix-row header"><span>${tr('ELEMENT / TARGET','元素／参考值')}</span><span>${tr('LIGHT','浅色')}</span><span>${tr('DARK','深色')}</span></div>`+pairs.map(([label,k,b,min,inactive])=>`<div class="matrix-row"><div>${label}<small>${min}:1 ${tr('reference','参考')}</small></div>${['light','dark'].map(t=>{if(k==='focus'&&!focused&&!actualFocus.has(t))return `<div class="result"><b>—</b><span>${tr('NOT FOCUSED','未聚焦')}</span></div>`;const r=ratioPair(t,k,b,inactive).ratio,ex=state==='disabled'&&inactive;return `<div class="result ${ex?'exempt':r>=min?'':'fail'}"><b>${r.toFixed(2)}:1</b><span>${ex?tr('EXEMPT','豁免'):r>=min?tr('PASS PAIR','对比度达标'):tr('REVIEW','需检查')}</span>${ex&&r<min?`<small>${tr('Low readability: increase foreground contrast or reduce dimming.','文字偏淡，建议加深文字或提高不透明度。')}</small>`:''}</div>`}).join('')}</div>`).join('');exportCode();}
function exportCode(){document.querySelectorAll('[data-format]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.format===format)));$('#code').value=format==='json'?JSON.stringify({schemaVersion:2,tool:'StateLens',version:'0.2.0',themes:palettes,assumptions:['sRGB source-over: backdrop → surface → fill → foreground','backdrop is declared opaque','disabled simulation uses group opacity 0.4'],scope:'Design-time token model, not real-component QA certification'},null,2):'/* StateLens token model; validate real rendered components. */\n'+Object.entries(palettes).map(([t,p])=>`[data-theme="${t}"] {\n${Object.entries(p).map(([k,v])=>`  --${k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())}: ${v};`).join('\n')}\n}`).join('\n\n');}
async function copy(text,status='#status'){try{await navigator.clipboard.writeText(text);$(status).textContent=tr('Copied.','已复制。');}catch{$(status).textContent=tr('Clipboard unavailable. Select and copy manually.','剪贴板不可用，请手动选择复制。');}}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function analyze(){snapshotText=$('#snapshot-json').value;try{lastReport=Snapshot.audit(snapshotText);$('#snapshot-status').textContent=tr('Results for this captured text.','已检查采集时的文字颜色。');$('#snapshot-result').innerHTML=lastReport.results.map(r=>`<article class="snapshot-row"><strong>${esc(r.id)} · ${esc(lang==='zh'?({pass:'对比度达标',fail:'需改进',exempt:'豁免／建议',unsupported:'无法判断'}[r.status]):r.status.toUpperCase())}</strong><span>${r.ratio==null?'—':Number(r.ratio).toFixed(2)+':1'} / ${r.threshold||'—'}:1</span><p>${esc((r.issues||[]).join('; '))}</p>${r.advisory?`<p>${esc(typeof r.advisory==='string'?r.advisory:JSON.stringify(r.advisory))}</p>`:''}</article>`).join('');}catch(e){lastReport=null;$('#snapshot-result').textContent='';$('#snapshot-status').textContent=tr('Invalid snapshot: ','快照无效：')+e.message;}}
function bind(){document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{theme=b.dataset.theme;tokens();render();});document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{state=b.dataset.state;render();});$('#focus-toggle').onchange=e=>{focused=e.target.checked;render();};document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{format=b.dataset.format;exportCode();});$('#reset').onclick=()=>{palettes=structuredClone(defaults);$('#status').textContent='';tokens();render();};$('#copy').onclick=()=>copy($('#code').value);$('#download').onclick=()=>download($('#code').value,'statelens-tokens.'+format);$('#snapshot-json').oninput=()=>{snapshotText=$('#snapshot-json').value;lastReport=null;$('#snapshot-result').textContent='';};$('#analyze').onclick=analyze;$('#report').onclick=()=>{if(lastReport)download(JSON.stringify(lastReport,null,2),'statelens-snapshot-report.json');else $('#snapshot-status').textContent=tr('Analyze a valid snapshot first.','请先检查有效快照。');};$('#example').onclick=()=>{snapshotText=JSON.stringify({schemaVersion:1,source:{kind:'computed-style',capturedAt:'example'},pairs:[{id:'Example text',state:'default',foreground:'rgba(20,40,30,.7)',backgrounds:['#ffffff'],backdrop:'#ffffff',disabled:false,fontSize:16,fontWeight:400,unsupported:[]},{id:'Example disabled text',state:'disabled',foreground:'#aaaaaa',backgrounds:['#ffffff'],backdrop:'#ffffff',disabled:true,fontSize:16,fontWeight:400,unsupported:[]},{id:'Example gradient',state:'default',foreground:'#111111',backgrounds:['#ffffff'],backdrop:'#ffffff',disabled:false,fontSize:16,fontWeight:400,unsupported:['background-image: gradient']} ]},null,2);$('#snapshot-json').value=snapshotText;analyze();};$('#collector').onclick=async()=>{try{const r=await fetch('capture.js');if(!r.ok)throw new Error('source unavailable');await copy(await r.text(),'#snapshot-status');}catch{$('#snapshot-status').textContent=tr('Open “Review collector source” and copy it manually.','请打开“审阅采集源码”手动复制。');}};$('#apca-pair').onclick=()=>{const pair=Contrast.evaluate(palettes[theme].foreground,palettes[theme].surface,palettes[theme].backdrop);copy(JSON.stringify({text:Contrast.toHex(pair.foreground),background:Contrast.toHex(pair.background),note:'Resolved opaque sRGB pair; consult APCA font guidance.'}));};}
$('#language').onclick=()=>{snapshotText=$('#snapshot-json').value;lang=lang==='en'?'zh':'en';scaffold();};scaffold();
